  const VLAN_FDDI = ["1002 fddi-default                     active    ", "1003 token-ring-default               active    ", "1004 fddinet-default                  active    ", "1005 trnet-default                    active    "];
  // Cabecera de show vlan brief.
  const VLAN_CABECERA = ["VLAN Name                             Status    Ports", "---- -------------------------------- --------- -------------------------------"];
